// Scratch diagnostic: preserve native total/event weights through the existing precise owner.
use color_eyre::{eyre::{ensure,eyre},Result};
use figment::{providers::Serialized,Figment};
use gammaloop_api::{commands::set::SetArgs,StateLoadOption};
use gammalooprs::{initialisation::initialise,integrands::{evaluation::{GenericEvaluationResult,PreciseEvaluationResult},process::{MomentumSpaceEvaluationInput,ProcessIntegrand,GraphTerm}},momentum::ThreeMomentum,utils::{F,FloatLike}};
use serde_json::{json,Value};
use std::{collections::BTreeSet,env,fs,time::Instant};
fn record<T:FloatLike>(r:GenericEvaluationResult<T>,precision:&str)->Result<Value>{
 ensure!(!r.evaluation_metadata.is_nan,"invalid physical result: {}",r.evaluation_metadata);
 ensure!(r.integrand_result.re.0.is_finite()&&r.integrand_result.im.0.is_finite(),"nonfinite total");
 let mut events=Vec::new();
 for (group_id,group) in r.event_groups.iter().enumerate(){for event in group.iter(){
  ensure!(event.weight.re.0.is_finite()&&event.weight.im.0.is_finite(),"nonfinite event");
  let extra=event.additional_weights.weights.iter().map(|(key,value)|json!({"key":format!("{key:?}"),"re":value.re.to_string(),"im":value.im.to_string()})).collect::<Vec<_>>();
  events.push(json!({"group":group_id,"cut_info":event.cut_info,"weight":{"re":event.weight.re.to_string(),"im":event.weight.im.to_string()},"additional_weights":extra}));
 }}
 Ok(json!({"precision":precision,"integrand_result":{"re":r.integrand_result.re.to_string(),"im":r.integrand_result.im.to_string()},"parameterization_jacobian":r.parameterization_jacobian.map(|v|v.to_string()),"integrator_weight":r.integrator_weight.to_string(),"events":events,"evaluation_metadata":r.evaluation_metadata}))
}
fn main()->Result<()>{
 initialise()?; let args=env::args().skip(1).collect::<Vec<_>>();ensure!(args.len()==3,"manifest requests output_directory");
 let manifest:Value=serde_json::from_str(&fs::read_to_string(&args[0])?)?;let requests:Value=serde_json::from_str(&fs::read_to_string(&args[1])?)?;
 let started=Instant::now();let mut loaded=StateLoadOption::read_only(manifest["state"].as_str().unwrap()).load()?;ensure!(loaded.is_read_only_state(),"state must remain read-only");loaded.state.activate_loaded_integrand_backends(false)?;
 let model=&loaded.state.model;let integrand=loaded.state.process_list.get_integrand_mut(0,"NNLO")?;let original=integrand.get_settings().clone();
 let mut previous=String::new();let mut summaries=Vec::new();
 for case in requests["cases"].as_array().unwrap().iter().filter(|c|c["momentum_space"]==true){
  let mode=case["mode"].as_str().unwrap();let enabled=case["threshold_ct_enabled"].as_bool().unwrap();let config=format!("{mode}:{enabled}");
  if config!=previous{
   let card=fs::read_to_string(manifest["cards"][mode].as_str().unwrap())?;
   let f=SetArgs::String{string:card}.merge_figment(Figment::from(Serialized::defaults(&original)))?;
   *integrand.get_mut_settings()=SetArgs::String{string:format!("general.generate_events=true\nsubtraction.disable_threshold_subtraction={}\n",!enabled)}.merge_figment(f)?.extract()?;
   std::thread::scope(|scope|->Result<()>{std::thread::Builder::new().stack_size(128*1024*1024).spawn_scoped(scope,||integrand.warm_up(model))?.join().map_err(|_|eyre!("warmup panic"))?})?;
   let ProcessIntegrand::CrossSection(p)=&*integrand else{return Err(eyre!("cross section expected"))};ensure!(p.data.graph_terms.len()==1&&p.data.graph_terms[0].selected_production_orientation_keys().len()==936,"actual full936 catalogue required");
   let term=&p.data.graph_terms[0];
   ensure!(term.graph.name=="GL638","expected actual GL638 graph");
   let keys=term.selected_production_orientation_keys();
   let key_set=keys.iter().map(|key|(*key).to_owned()).collect::<BTreeSet<_>>();
   let expected_keys:Vec<String>=serde_json::from_str(&fs::read_to_string(manifest["expected_production_keys"].as_str().unwrap())?)?;
   ensure!(key_set.len()==936&&key_set==expected_keys.into_iter().collect(),"actual complete production key set changed");
   let vectors=keys.iter().map(|key|->Result<Vec<i64>>{
    let body=key.strip_prefix("O[").and_then(|key|key.split_once(']')).ok_or_else(||eyre!("unrecognized production orientation key {key}"))?.0;
    body.chars().map(|c|match c{'+' => Ok(1),'-' => Ok(-1),'x' => Ok(0),_ => Err(eyre!("invalid orientation character {c}"))}).collect()
   }).collect::<Result<BTreeSet<_>>>()?;
   let expected_vectors:Vec<Vec<i64>>=serde_json::from_str(&fs::read_to_string(manifest["expected_orientation_vectors"].as_str().unwrap())?)?;
   ensure!(vectors.len()==936&&vectors==expected_vectors.into_iter().collect(),"actual complete orientation vector set changed");
   let cuts=term.cut_esurface.iter().enumerate().map(|(id,surface)|json!({"id":id,"energy_edges":surface.energies.iter().map(|edge|edge.0).collect::<Vec<_>>(),"external_shift":format!("{:?}",surface.external_shift)})).collect::<Vec<_>>();
   let expected_cuts:Value=serde_json::from_str(&fs::read_to_string(manifest["expected_cut_registry"].as_str().unwrap())?)?;
   ensure!(json!(cuts)==expected_cuts,"physical cut equations changed");
   fs::write(format!("{}/production_inventory.json",args[2]),serde_json::to_string_pretty(&json!({"graph":term.graph.name,"actual_production_keys":keys,"actual_orientation_vectors":vectors,"cut_registry":cuts,"full_key_set_equal":true,"full_vector_set_equal":true}))?)?;
   let cut_groups=term.cut_group_data.cut_groups.iter().enumerate().map(|(id,g)|json!({"group_id":id,"cut_ids":g.cuts.iter().map(|c|c.0).collect::<Vec<_>>(),"max_occurrence":g.related_esurface_group.max_occurence})).collect::<Vec<_>>();
   ensure!(cut_groups.len()==6&&cut_groups.iter().all(|g|g["max_occurrence"]==1),"expected six simple physical cut groups");
   fs::write(format!("{}/cut_groups.json",args[2]),serde_json::to_string_pretty(&cut_groups)?)?;
   fs::write(format!("{}/{}.settings.toml",args[2],config.replace(':',"_")),toml::to_string_pretty(integrand.get_settings())?)?;previous=config;
  }
  let point=case["point_tokens"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().parse::<f64>()).collect::<std::result::Result<Vec<_>,_>>()?;
  let input=MomentumSpaceEvaluationInput{loop_momenta:point.chunks_exact(3).map(|v|ThreeMomentum::from([F(v[0]),F(v[1]),F(v[2])])).collect(),integrator_weight:F(1.),graph_id:Some(0),group_id:None,orientation:None,channel_id:None};
  let at=Instant::now();let native=integrand.evaluate_momentum_configuration_precise(model,&input,case["forced_arb"].as_bool().unwrap())?;
  let result=match native{PreciseEvaluationResult::Double(r)=>record(r,"Double")?,PreciseEvaluationResult::Quad(r)=>record(r,"Quad")?,PreciseEvaluationResult::Arb(r)=>record(r,"Arb")?};
  let row=json!({"case":case,"evaluation":result,"elapsed_seconds":at.elapsed().as_secs_f64(),"point_definition":"original binary64 tokens, promoted by existing source precision owner"});
  let name=case["name"].as_str().unwrap();fs::write(format!("{}/{name}.json",args[2]),serde_json::to_string_pretty(&row)?)?;println!("completed{name} {}s",at.elapsed().as_secs_f64());summaries.push(json!({"name":name,"elapsed_seconds":at.elapsed().as_secs_f64()}));
 }
 fs::write(format!("{}/summary.json",args[2]),serde_json::to_string_pretty(&json!({"cases":summaries,"elapsed_seconds":started.elapsed().as_secs_f64()}))?)?;Ok(())
}

