from pathlib import Path
import datetime,decimal,hashlib,json,subprocess,time
r=Path(__file__).resolve().parent
run=json.loads((r/'run-provenance.json').read_text());assert run['returncode']==0,run
subprocess.run(['python3',str(r/'compare.py')],check=True)
comparison=json.loads((r/'comparison.json').read_text())
for case in comparison['cases']:
 assert case['event_identity_equal'] and case['old_event_count']==case['new_event_count']==6
 assert not case['old_is_nan'] and not case['new_is_nan']
 for which in ['old_total','new_total']:
  assert all(decimal.Decimal(v).is_finite() for v in case[which].values())
 for event in case['events']:
  for which in ['old_weight','new_weight']:
   assert all(decimal.Decimal(v).is_finite() for v in event[which].values())
inventory=json.loads((r/'results/production_inventory.json').read_text())
assert inventory['full_key_set_equal'] and inventory['full_vector_set_equal']
assert len(inventory['actual_production_keys'])==len(inventory['actual_orientation_vectors'])==936
before=json.loads((r/'state-integrity-before.json').read_text());expected=before['sha256'];state=Path(before['state_directory']);start=time.monotonic()
files={str(p.relative_to(state)) for p in state.rglob('*') if p.is_file()}
assert files==set(expected),{'added':sorted(files-set(expected)),'missing':sorted(set(expected)-files)}
actual={}
for rel,wanted in expected.items():
 h=hashlib.sha256()
 with (state/rel).open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 actual[rel]=h.hexdigest();assert actual[rel]==wanted,(rel,actual[rel],wanted)
(r/'state-integrity-after.json').write_text(json.dumps({'verified_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'state_directory':str(state),'file_count':len(files),'complete_file_set_equal':True,'all_hashes_unchanged':True,'sha256':actual,'elapsed_seconds':time.monotonic()-start},indent=2)+'\n')
manifest=json.loads((r/'manifest.json').read_text());manifest['link_status']='frozen current-source replay completed successfully';manifest['replay_returncode']=run['returncode'];manifest['post_state_unchanged']=True
(r/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print(json.dumps({'elapsed_seconds':run['elapsed_seconds'],'actual_key_count':len(inventory['actual_production_keys']),'actual_vector_count':len(inventory['actual_orientation_vectors']),'state_files_unchanged':len(files),'cases':[{'name':c['case'],'old_precision':c['old_precision'],'new_precision':c['new_precision'],'relative_total':c['relative_total_complex_norm'],'max_event_relative':c['max_event_relative_complex_norm']} for c in comparison['cases']]},indent=2))

